-- 01 · READ-ONLY: which org lands in which org schema.
SELECT o.name, CASE WHEN o.name ILIKE 'Biofuel%' THEN 'org_biofuel' WHEN o.name ILIKE 'CIEL%' THEN 'org_ciel' WHEN o.name ILIKE 'Cappitech%' THEN 'org_cappitech' WHEN o.name ILIKE 'Osiris Technology%' THEN 'org_osiris' WHEN o.name ILIKE '%your%world%' THEN 'org_yourworld' WHEN o.name ILIKE 'U2CAN%' THEN 'org_u2can' WHEN o.name ILIKE 'osiris-platform%' THEN 'org_platformorg' WHEN o.name ILIKE 'Asia Deal Hub%' THEN 'org_adhjapan' WHEN o.name ILIKE 'Chong Aik%' THEN 'org_chongaik' WHEN o.name ILIKE 'Denzel%' THEN 'org_denzel' WHEN o.name ILIKE 'DEMO INDUSTRIES%' THEN 'org_demoindustries' WHEN o.name ILIKE 'DEMO INTERIOR%' THEN 'org_demointerior' WHEN o.name ILIKE 'WCT' THEN 'org_wct' END AS org_schema, o.id FROM public."Organization" o ORDER BY 2 NULLS FIRST, 1;
